/* 确保按钮容器本身不影响图标显示 */
.mes_buttons {
    display: flex !important;
    align-items: center !important;
    gap: 4px !important;                   /* ✏️【按钮间距】可调整 */
}

/* 世界书激活时按钮颜色 */
.world_set, 
.toggleEnabled {
    color: rgba(129, 129, 129, 1) !important;    /* ✏️【世界书激活颜色】 */
}

/* 角色收藏时按钮颜色 */
.fav_on {
    color: rgba(202, 202, 202, 1) !important;    /* ✏️【收藏激活颜色】 */
}

/* --- 1. 扩展面板/设置区的按钮和标题 --- */
.inline-drawer-toggle,
.standoutHeader,
.extension_button,
#user-settings-block h4,
.inline-drawer-header {
    /* 移除默认的灰色渐变背景 */
    background-image: none !important;

    /* 背景颜色 - 纯白 */
    background-color: #FFFFFF !important;

    /* 边框 - 黑 */
    border: 1px solid rgba(246, 246, 246, 1) !important;  /* ✏️【边框】 */


    /* 其他美化样式 */
    border-radius: 12px !important;
    box-shadow: 0 2px 5px （128, 128, 128, 0.3） !important; /* ✏️【阴影】 */
}

/* 鼠标悬停时的样式 */
.inline-drawer-toggle:hover,
.extension_button:hover {
    border-color: #BDBDBD !important;
    box-shadow: 0 0 8px rgba(196, 196, 196, 0.3) !important;  /* ✏️【悬停阴影】 */
}


/* --- 2. 多选标签 (例如：世界书标签) --- */
.select2-container--default .select2-selection--multiple .select2-selection__choice {
    /* 移除默认的灰色渐变背景 */
    background-image: none !important;

    /* 背景颜色 - 纯白 */
    background-color: #FFFFFF !important;

    /* 边框 - 浅黑色 */
    border: 1px solid rgba(152, 152, 152, 1) !important;   /* ✏️【标签边框】浅黑色 */

    /* 文字颜色 - 深黑色 */
    color: #101010 !important;               /* ✏️【标签文字】深黑色 */

    /* 圆角 */
    border-radius: 8px !important;
}

/* 整个多选框的容器样式 */
.select2-container--default .select2-selection--multiple {
    background-image: none !important;
    background-color: #FFFFFF !important;
    border: 1px solid rgba(188, 188, 188, 1) !important;   /* ✏️【容器边框】浅灰色 */
    border-radius: 12px !important;
}

/* 当多选框被激活(点击)时的样式 */
.select2-container--default.select2-container--open .select2-selection--multiple {
    border-color: #FFFFFF !important;        /* ✏️【激活边框】白色 */
    box-shadow: 0 0 8px rgba(123, 123, 123, 0.79) !important;
}

/* ===== 全局白底设置 ===== */

