    border-color: #1E1E1E !important;  /* ✏️【面板边框】改为浅黑 */
}

/* 输入框背景变白 */
select,
input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),
textarea {
    background-color: #FFFFFF !important;
    border: 1px solid rgba(138, 138, 138, 1) !important;  /* ✏️【输入框边框】浅灰色 */
    color: #000000 !important;
}

/* 下拉菜单选项背景 */
option {
    background-color: #FFFFFF !important;
    color: #000000 !important;
}

