.api_button:hover {
    background-color: rgba(103, 103, 103, 1) !important;  /* ✏️【悬停背景】更深的浅灰 */
}

/* 消息区域背景 */
.mes {
    background-color: rgba(255, 255, 255, 0.9) !important;
}


/* 顶栏背景 */
#top-settings-holder {
    background-color: #FFFFFF !important;
    border-bottom: 1px solid rgba(102, 102, 102, 1) !important;  /* ✏️【顶栏边框】浅灰色 */
}

/* 如果背景图导致透出黑色，可以临时注释掉背景图 */
